/**
 * Bound-parameter budget for one SQL statement on this project's database
 * driver, and helpers that split batch work to stay under it.
 *
 * D1 rejects the 101st bind with "too many SQL variables"; Postgres allows
 * 65535. The generated batch routes never build a statement whose bind count
 * depends on request size without going through one of these helpers.
 */
export const MAX_SQL_BINDS = 100;

/**
 * Binds a chunk leaves free for the clauses that ride alongside the list —
 * the firewall's scope claims, soft-delete audit values, a `via:` subquery.
 */
const BIND_RESERVE = 20;

/** Ids per `IN (...)` slice. */
export const ID_CHUNK = Math.max(1, MAX_SQL_BINDS - BIND_RESERVE);

/**
 * Rows per INSERT slice. Drizzle fills every column of the TABLE for every row
 * at execution time — `$defaultFn` ids and timestamps, audit and firewall
 * columns the request never sent — so the payload's keys undercount the binds
 * (#676: 5 keys on an 87-column table sized slices at 16 rows). Divide the
 * budget by the table's column count when `table` is given, else by the
 * widest row. A single row wider than the budget still goes out alone; one
 * row binds at most one value per column, and it cannot be split further.
 */
export function rowChunkSize(rows: readonly Record<string, unknown>[], table?: any): number {
  const columns = new Set<string>();
  for (const row of rows) {
    for (const key of Object.keys(row)) {
      if (row[key] !== undefined) columns.add(key);
    }
  }
  // Drizzle keeps a table's columns under this registered symbol (what
  // getTableColumns reads); anything else — a test double — has none.
  const tableColumns = table?.[Symbol.for('drizzle:Columns')];
  const width = Math.max(columns.size, tableColumns ? Object.keys(tableColumns).length : 0);
  return Math.max(1, Math.floor((MAX_SQL_BINDS - BIND_RESERVE) / Math.max(1, width)));
}

/**
 * Run `build(slice)` over `values` in slices of `size` and concatenate the
 * rows. One slice → the query runs as-is (no behavior change under the cap).
 * Several slices → `db.batch([...])` when the handle offers it (D1, libsql,
 * neon-http: the slices commit together) else sequential awaits.
 */
export async function inChunks<R>(
  db: any,
  values: readonly any[],
  size: number,
  build: (slice: any[]) => any,
): Promise<R[]> {
  if (values.length <= size) return ((await build([...values])) ?? []) as R[];
  const slices: any[][] = [];
  for (let i = 0; i < values.length; i += size) slices.push(values.slice(i, i + size));
  if (typeof db?.batch === 'function') {
    const results: R[][] = await db.batch(slices.map(build) as any);
    return results.flat();
  }
  const out: R[] = [];
  for (const slice of slices) {
    const result = await build(slice);
    if (Array.isArray(result)) out.push(...(result as R[]));
    else if (result !== undefined) out.push(result as R);
  }
  return out;
}

/** `build` receives a slice of `ids` to put in its `inArray(col, slice)`. */
export function selectInChunks<R = any>(db: any, ids: readonly any[], build: (slice: any[]) => any): Promise<R[]> {
  return inChunks<R>(db, ids, ID_CHUNK, build);
}

/** Multi-row INSERT ... RETURNING, sliced by column width. */
export function insertInChunks<R = any>(db: any, table: any, rows: Record<string, unknown>[]): Promise<R[]> {
  return inChunks<R>(db, rows, rowChunkSize(rows, table), (slice) => db.insert(table).values(slice).returning());
}

